-- Marca como vendidos los 76 puestos de servicios (S-911..S-986), segun la
-- actualizacion del Excel oficial del 2026-11-15 (bancos, telefonia, farmacia,
-- apuestas, libreria, etc. pasan de disponible a VENDIDO).
-- Respeta separaciones en curso; tambien convierte si quedaron 'bloqueado'.
begin;
lock table public.puestos in share row exclusive mode;
create temporary table _omitidos(codigo text, estado text) on commit drop;
insert into _omitidos select 'S-911', estado from public.puestos where codigo='S-911' and estado='separado';
update public.puestos set estado='vendido', motivo_bloqueo=null, version=version+1, actualizado_en=now() where codigo='S-911' and estado in ('disponible','bloqueado');
